module main:
- w1: atomic_load {"dst": "old", "resource": "main::c"}; atomic_cas {"desired": "old + 1", "dst": "seen", "expected": "old", "resource": "main::c"}; branch {"cond": "seen == old", "else": "s1", "then": "s5"}; return {}
