    let c_guard = c.lock().unwrap();

    let mut work = 0;
    work = work + 1;

    drop(c_guard);
    drop(a_guard);
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));
    let c = Arc::new(Mutex::new(()));

    let t1_handle = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        thread::spawn(move || t1(a, b))
    };
    let t2_handle = {
        let b = Arc::clone(&b);
        let c = Arc::clone(&c);
        thread::spawn(move || t2(b, c))
    };
    let t3_handle = {
        let a = Arc::clone(&a);
        let c = Arc::clone(&c);
        thread::spawn(move || t3(a, c))
    };

    t1_handle.join().unwrap();
    t2_handle.join().unwrap();
    t3_handle.join().unwrap();

    println!("DONE done=1");
