use concir_sync::{Permit, Semaphore};
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

fn w1(
    m: Arc<Mutex<bool>>,
    cv: Arc<Condvar>,
    g12: Arc<Semaphore>,
    gN: Arc<Semaphore>,
    g12_permit: Permit,
) {
    let mut proceed = m.lock().unwrap();
    while !*proceed {
        g12_permit.release();
        proceed = cv.wait(proceed).unwrap();
    }
    drop(proceed);
    let _permit = gN.acquire();
}

fn w2(
    m: Arc<Mutex<bool>>,
    cv: Arc<Condvar>,
    g12: Arc<Semaphore>,
    gN: Arc<Semaphore>,
    g12_permit: Permit,
) {
    let mut proceed = m.lock().unwrap();
    while !*proceed {
        g12_permit.release();
        proceed = cv.wait(proceed).unwrap();
    }
    drop(proceed);
    let _permit = gN.acquire();
}

fn notifier(
    m: Arc<Mutex<bool>>,
    cv: Arc<Condvar>,
    g12: Arc<Semaphore>,
    gN_permit1: Permit,
    gN_permit2: Permit,
) {
    let _permit1 = g12.acquire();
    let _permit2 = g12.acquire();

    let mut proceed = m.lock().unwrap();
    *proceed = true;
    cv.notify_all();
    gN_permit1.release();
    gN_permit2.release();
    drop(proceed);
}

fn main() {
    let m = Arc::new(Mutex::new(false));
    let cv = Arc::new(Condvar::new());
    let g12 = Semaphore::new(2);
    let gN = Semaphore::new(2);

    let g12_permit1 = g12.acquire();
    let g12_permit2 = g12.acquire();
    let gN_permit1 = gN.acquire();
